  const act=aS/8,inh=iS/8,delay=dS/8;
  const bg=(Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1)+Math.sin(dx*0.08+dy*0.06-t*1.5)*0.5+Math.sin(dx*0.12-dy*0.09+t*2.0)*0.25)/2+Math.sin((dx+dy)*0.12+t*2.5)*0.2+Math.sin((dx-dy)*0.1-t*2)*0.2;
